items.body_excerpt:
{

 "meta":{

 "title":"Greetings to the Universe in 55 Different Languages",

 "source":"https://voyager.jpl.nasa.gov/golden-record/whats-on-the-record/greetings/",

 "description":"A golden phonograph record was attached to each of the Voyager spacecraft. One of the purposes was to send a message to extraterrestrials who might find the spacecraft as the spacecraft journeyed through interstellar space. In addition to pictures and music and sounds from earth, greetings in 55 languages were included."

 },

 "data":[

 [

 {

 "Title":"Gujarati",

 "Speaker":"Radhekeant Dave",

 "Translation":"Greetings from a human being of the Earth. Please contact.",

 "Inscription":"1b509d0177d16fd78e68b46db3de753935e3406ad0d7cc1bcc3062e683c9a46bi0"

 },

 {

 "Title":"Persian",

 "Speaker":"Eshagh Samehyeh",

 "Translation":"Hello to the residents of far skies.",

 "Inscription":"760df1efc541a64942149234ad223f376fad95efdf962b77f080f9395353f8f6i0"

 },

 {

 "Title":"Urdu",

 "Speaker":"Salma Alzal",

 "Translation":"Peace on you. We the inhabitants of this earth send our greetings to you.",

 "Inscription":"2270358f82606520198ef5f967d45ea9836f9d7b91aff8030a23df0bd6233957i0"

 },

 {

 "Title":"Swedish",

 "Speaker":"Gunnel Almgren Schaar",

 "Translation":"Greetings from a computer programmer in the little university town of Ithaca on the planet Earth",

 "Inscription":"35d6cac748b703c2dbe746ebbdf66d7d0e816492e5324c1ba78409e43ab94da5i0"

 },

 {

 "Title":"Marathi",

 "Speaker":"Arati Pandit",

 "Translation":"Greetings. The people of the Earth send their good wishes.",

 "Inscription":"ea945c3ba1e3313621732d26d8c17efaf5416b56157f5ffbc063969e8c39d566i0"

 },

 {

 "Title":"Oriya",

 "Speaker":"Raghaba Prasada Sahu",

 "Translation":"Greetings to the inhabitants of the universe from the third planet Earth of the star Sun.",

 "Inscription":"c6831f013be40a760e34ce5783ddd803e8da7c9e3e7c2378a3e68c306bbca8d9i0"

 },

 {

 "Title":"Armenian",

 "Speaker":"Araxy Terzian",

 "Translation":"To all those who exist in the universe, greetings.",

 "Inscription":"034302afd09410824e45433cd0d8f87c299b11ab07c18316860023f8440a2b17i0"

 },

 {

 "Title":"Latin",

 "Speaker":"Frederick M. Ahl",

 "Translation":"Greetings to you, whoever you are; we have good will towards you and bring peace across space.",

 "Inscription":"bc881feb0825cab36c50ee833b75e2c951e1e78f028eced21ab55955c2dfada5i0"

 },

 {

 "Title":"Greek",

 "Speaker":"Frederick M. Ahl",

 "Translation":"Greetings to you, whoever you are. We come in friendship to those who are friends.",

 "Inscription":"9735fa9fce8ca0bb9f6211be02ba97cd14090f1acc69d56a21f0da7b28c1ba9di0"

 },

 {

 "Title":"Amoy (Min dialect)",

 "Speaker":"Margaret Sook Ching See Gebauer",

 "Translation":"Friends of space, how are you all? Have you eaten yet? Come visit us if you have time.",

 "Inscription":"29fd0b15bcc15aa7d8e18ed55c886799714958c8077d068bc89b549210027fefi0"

 },

 {

 "Title":"Thai",

 "Speaker":"Ruchira Mendiones",

 "Translation":"We in this world send you our good will",

 "Inscription":"a496118cb41ddb49b880f165c6836a1de23170721983cb11aee1fc8ce51b97b2i0"

 },

 {

 "Title":"Rajasthani",

 "Speaker":"Mool C. Gupta",

 "Translation":"Hello to everyone. We are happy here and you be happy there.",

 "Inscription":"378c3ccccdec70a73d9c264b4c3e2a3cc5292f45045db6c92278ab13ae0d58a0i0"

 },

 {

 "Title":"Hungarian (Magyar)",

 "Speaker":"Elizabeth Bilson",

 "Translation":"We are sending greetings in the Hungarian language to all peace-loving beings in the Universe.",

